BEGIN;
DO $$
DECLARE
  v_subject_id UUID;
  v_topic_id UUID;
  v_test_id BIGINT;
BEGIN
  SELECT id INTO v_subject_id FROM test_subjects WHERE name ILIKE '%cardio%' ORDER BY id LIMIT 1;
  IF v_subject_id IS NULL THEN
    INSERT INTO test_subjects (name, description) VALUES ('Cardiovascular System', 'Cardiovascular notes') RETURNING id INTO v_subject_id;
  END IF;
  SELECT id INTO v_topic_id FROM test_topics WHERE name = 'Pericarditis' ORDER BY (SELECT COUNT(*) FROM test_questions q WHERE q.topic_id = test_topics.id) DESC, created_at ASC LIMIT 1;
  IF v_topic_id IS NULL THEN
    INSERT INTO test_topics (subject_id, name, description, status) VALUES (v_subject_id, 'Pericarditis', 'Inflammation, EKG changes, MI differential, treatment', 'published') RETURNING id INTO v_topic_id;
  END IF;
  SELECT id INTO v_test_id FROM tests WHERE is_active = true ORDER BY id LIMIT 1;
  IF v_test_id IS NULL THEN
    INSERT INTO tests (test_name, system_category, description, is_active)
    VALUES ('Cardiovascular System - Pericarditis (Generated)', 'Cardiovascular System', 'Auto-generated NCLEX question set', true)
    RETURNING id INTO v_test_id;
  END IF;
  DELETE FROM test_questions WHERE topic_id = v_topic_id AND category = 'Pericarditis - NCLEX';
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pericarditis note, which statement about "Definition" is most accurate?', 'According to the Pericarditis note, which statement about "Definition" is most accurate?', '[{"id": "a", "text": "Pericarditis is confined to coronary arteries."}, {"id": "b", "text": "The pericardium is the sac around the heart."}, {"id": "c", "text": "Friction rub is a definitive MI finding."}, {"id": "d", "text": "Pericarditis is inflammation of heart valves."}]'::jsonb, '["b"]'::jsonb, 'Correct because Pericarditis is inflammation of the pericardium, the fibrous sac surrounding the heart. Identify inflammatory pericardial pain patterns early to prevent complications.', 'Pericarditis - NCLEX', false, 1, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Disease course" in Pericarditis. Which statement is correct?', 'The nurse is reviewing "Disease course" in Pericarditis. Which statement is correct?', '[{"id": "a", "text": "Pericarditis can be acute, recurrent, or chronic constrictive."}, {"id": "b", "text": "Pericarditis is always single-episode and never recurrent."}, {"id": "c", "text": "Constrictive disease is unrelated to pericarditis."}, {"id": "d", "text": "The best approach is to defer EKG differentiation until outpatient review."}]'::jsonb, '["a"]'::jsonb, 'Correct because Pericarditis can be acute, recurrent, or chronic constrictive. Recurrent patterns require recurrence-prevention therapy and follow-up.', 'Pericarditis - NCLEX', false, 2, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Effusion complication" in Pericarditis?', 'Which clinical judgment is most accurate regarding "Effusion complication" in Pericarditis?', '[{"id": "a", "text": "Tamponade is a harmless expected phase."}, {"id": "b", "text": "Pericardial inflammation can produce effusion."}, {"id": "c", "text": "Dressler syndrome is bacterial endocarditis."}, {"id": "d", "text": "Dressler syndrome occurs immediately during MI."}]'::jsonb, '["b"]'::jsonb, 'Correct because Fluid accumulation can cause pericardial effusion, and large effusions can lead to cardiac tamponade. Escalate promptly when effusion signs appear because tamponade is life-threatening.', 'Pericarditis - NCLEX', false, 3, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Common causes" in Pericarditis?', 'In rapid prioritization, which statement is most consistent with "Common causes" in Pericarditis?', '[{"id": "a", "text": "Immediate escalation is unnecessary because complication risk is negligible."}, {"id": "b", "text": "Pericarditis is almost never viral."}, {"id": "c", "text": "The best approach is to defer EKG differentiation until outpatient review."}, {"id": "d", "text": "Viral causes are most common, and many cases are idiopathic."}]'::jsonb, '["d"]'::jsonb, 'Correct because Viral causes are most common, and many cases are idiopathic. Prioritize broad etiologic review while managing inflammation and pain.', 'Pericarditis - NCLEX', false, 4, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Systemic/infectious causes" in Pericarditis would the nurse recognize as correct?', 'Which conclusion about "Systemic/infectious causes" in Pericarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Dyspnea never occurs in pericarditis."}, {"id": "b", "text": "Trapezius radiation excludes pericarditis."}, {"id": "c", "text": "SLE/RA/scleroderma are autoimmune causes."}, {"id": "d", "text": "Pericarditis is unrelated to renal failure."}]'::jsonb, '["c"]'::jsonb, 'Correct because Bacterial TB/S. aureus, autoimmune disease, uremia, malignancy, radiation, trauma, surgery, and medications are listed causes. Tailor treatment to the underlying cause while controlling inflammation.', 'Pericarditis - NCLEX', false, 5, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pericarditis note, which statement about "Dressler syndrome timing" is most accurate?', 'According to the Pericarditis note, which statement about "Dressler syndrome timing" is most accurate?', '[{"id": "a", "text": "EKG pattern is fixed and never evolves."}, {"id": "b", "text": "Dressler syndrome is bacterial endocarditis."}, {"id": "c", "text": "Electrical alternans excludes effusion."}, {"id": "d", "text": "Dressler syndrome can occur after MI."}]'::jsonb, '["d"]'::jsonb, 'Correct because Dressler syndrome is autoimmune pericarditis occurring 1–6 weeks after MI or cardiac surgery. Recognize delayed post-MI/surgical chest pain as possible Dressler syndrome.', 'Pericarditis - NCLEX', false, 6, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Classic pain profile" in Pericarditis. Which statement is correct?', 'The nurse is reviewing "Classic pain profile" in Pericarditis. Which statement is correct?', '[{"id": "a", "text": "Use positional and pleuritic features to distinguish from ischemic chest pain patterns."}, {"id": "b", "text": "Pain is position-independent pressure pain."}, {"id": "c", "text": "Immediate escalation is unnecessary because complication risk is negligible."}, {"id": "d", "text": "The best approach is to defer EKG differentiation until outpatient review."}]'::jsonb, '["a"]'::jsonb, 'Correct because Pericarditis pain is sharp/pleuritic, worse with inspiration and lying flat, and relieved by sitting up/leaning forward. Use positional and pleuritic features to distinguish from ischemic chest pain patterns.', 'Pericarditis - NCLEX', false, 7, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Radiation and associated symptoms" in Pericarditis?', 'Which clinical judgment is most accurate regarding "Radiation and associated symptoms" in Pericarditis?', '[{"id": "a", "text": "Pericarditis causes only contiguous territorial ST elevation."}, {"id": "b", "text": "Troponin is never elevated in any pericarditis scenario."}, {"id": "c", "text": "Link systemic symptoms with inflammatory etiology during triage."}, {"id": "d", "text": "Trapezius radiation excludes pericarditis."}]'::jsonb, '["c"]'::jsonb, 'Correct because Pain can radiate to left shoulder/trapezius; fever, malaise, myalgia, and dyspnea can occur. Link systemic symptoms with inflammatory etiology during triage.', 'Pericarditis - NCLEX', false, 8, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Friction rub hallmark" in Pericarditis?', 'In rapid prioritization, which statement is most consistent with "Friction rub hallmark" in Pericarditis?', '[{"id": "a", "text": "Friction rub is a definitive MI finding."}, {"id": "b", "text": "Colchicine is contraindicated in all pericarditis."}, {"id": "c", "text": "Best heard at left sternal border while leaning forward."}, {"id": "d", "text": "Opioids are listed as definitive first-line therapy."}]'::jsonb, '["c"]'::jsonb, 'Correct because Pericardial friction rub is pathognomonic: high-pitched scratchy/grating, best heard at left sternal border with patient leaning forward. Prioritize focused auscultation technique to capture fleeting rub findings.', 'Pericarditis - NCLEX', false, 9, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Rub nuances" in Pericarditis would the nurse recognize as correct?', 'Which conclusion about "Rub nuances" in Pericarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Persistent rub is required throughout all stages."}, {"id": "b", "text": "No activity limits are needed during acute phase."}, {"id": "c", "text": "Effusion makes rub louder by increasing friction."}, {"id": "d", "text": "Loss of rub does not exclude worsening complications."}]'::jsonb, '["d"]'::jsonb, 'Correct because The rub may be triphasic and can disappear if effusion develops as fluid separates pericardial layers. Do not rule out pericarditis solely because rub is absent later in disease.', 'Pericarditis - NCLEX', false, 10, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pericarditis note, which statement about "Diffuse ST elevation" is most accurate?', 'According to the Pericarditis note, which statement about "Diffuse ST elevation" is most accurate?', '[{"id": "a", "text": "Pericarditis causes only contiguous territorial ST elevation."}, {"id": "b", "text": "SLE-related pericarditis should avoid steroids."}, {"id": "c", "text": "Saddle-shaped morphology is associated with pericarditis."}, {"id": "d", "text": "Steroids are mandatory first-line for all cases."}]'::jsonb, '["c"]'::jsonb, 'Correct because Pericarditis classically shows diffuse (all-lead) saddle-shaped ST elevation. Differentiate diffuse inflammatory ST elevation from territorial ischemic patterns.', 'Pericarditis - NCLEX', false, 11, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "PR depression" in Pericarditis. Which statement is correct?', 'The nurse is reviewing "PR depression" in Pericarditis. Which statement is correct?', '[{"id": "a", "text": "PR changes are irrelevant in pericarditis."}, {"id": "b", "text": "PR direction contrasts with ST elevation."}, {"id": "c", "text": "PR elevation is the classic early finding."}, {"id": "d", "text": "MI pain improves when leaning forward."}]'::jsonb, '["b"]'::jsonb, 'Correct because PR depression is a classic early pericarditis finding and opposite ST direction. Use PR deviation as a high-yield discriminator in early interpretation.', 'Pericarditis - NCLEX', false, 12, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "No reciprocal changes" in Pericarditis?', 'Which clinical judgment is most accurate regarding "No reciprocal changes" in Pericarditis?', '[{"id": "a", "text": "Reciprocal ST depression is absent in pericarditis."}, {"id": "b", "text": "Reciprocal changes have no differential value."}, {"id": "c", "text": "Pericarditis requires reciprocal ST depression."}, {"id": "d", "text": "Troponin is never elevated in any pericarditis scenario."}]'::jsonb, '["a"]'::jsonb, 'Correct because Pericarditis has no reciprocal ST depression, unlike MI. Avoid mislabeling diffuse pericarditis as STEMI when reciprocal changes are absent.', 'Pericarditis - NCLEX', false, 13, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Later EKG evolution" in Pericarditis?', 'In rapid prioritization, which statement is most consistent with "Later EKG evolution" in Pericarditis?', '[{"id": "a", "text": "EKG pattern is fixed and never evolves."}, {"id": "b", "text": "Opioids are listed as definitive first-line therapy."}, {"id": "c", "text": "Electrical alternans can accompany large effusion."}, {"id": "d", "text": "Colchicine is contraindicated in all pericarditis."}]'::jsonb, '["c"]'::jsonb, 'Correct because T-wave inversion may appear in later stages; electrical alternans can appear with large effusion. Interpret EKG changes in temporal context and effusion severity.', 'Pericarditis - NCLEX', false, 14, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Pericarditis vs MI pain differences" in Pericarditis would the nurse recognize as correct?', 'Which conclusion about "Pericarditis vs MI pain differences" in Pericarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Tamponade surveillance is unnecessary in pericarditis."}, {"id": "b", "text": "Pericarditis pain is classically crushing pressure."}, {"id": "c", "text": "Pericarditis pain is often pleuritic and positional."}, {"id": "d", "text": "No activity limits are needed during acute phase."}]'::jsonb, '["c"]'::jsonb, 'Correct because Pericarditis pain is gradual, sharp, pleuritic, and positional; MI pain is sudden, crushing, pressure-like, and non-positional. Use symptom quality and positional response to sharpen early triage decisions.', 'Pericarditis - NCLEX', false, 15, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pericarditis note, which statement about "Pericarditis vs MI EKG/lab clues" is most accurate?', 'According to the Pericarditis note, which statement about "Pericarditis vs MI EKG/lab clues" is most accurate?', '[{"id": "a", "text": "Localized ST elevation with reciprocal changes supports MI."}, {"id": "b", "text": "Localized-only ST elevation is required for diagnosis."}, {"id": "c", "text": "Reciprocal ST depression is a hallmark of pericarditis."}, {"id": "d", "text": "Troponin is never elevated in any pericarditis scenario."}]'::jsonb, '["a"]'::jsonb, 'Correct because Pericarditis: diffuse ST elevation + PR depression + absent Q waves; MI: localized ST elevation, reciprocal changes, Q waves in STEMI, higher troponin rise. Integrate EKG with biomarker pattern to avoid anchoring errors.', 'Pericarditis - NCLEX', false, 16, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "First-line therapy" in Pericarditis. Which statement is correct?', 'The nurse is reviewing "First-line therapy" in Pericarditis. Which statement is correct?', '[{"id": "a", "text": "Pericarditis is confined to coronary arteries."}, {"id": "b", "text": "Colchicine is added to reduce recurrence risk."}, {"id": "c", "text": "Colchicine is contraindicated in all pericarditis."}, {"id": "d", "text": "Pericarditis is inflammation of heart valves."}]'::jsonb, '["b"]'::jsonb, 'Correct because First-line treatment is NSAIDs (ibuprofen/aspirin) plus colchicine to reduce recurrence risk. Start anti-inflammatory therapy early and include recurrence prevention.', 'Pericarditis - NCLEX', false, 17, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Activity guidance" in Pericarditis?', 'Which clinical judgment is most accurate regarding "Activity guidance" in Pericarditis?', '[{"id": "a", "text": "No activity limits are needed during acute phase."}, {"id": "b", "text": "Pericarditis is always single-episode and never recurrent."}, {"id": "c", "text": "Strenuous exercise should be avoided until symptom-free."}, {"id": "d", "text": "Tamponade in pericarditis is managed with observation only."}]'::jsonb, '["c"]'::jsonb, 'Correct because Rest and activity restriction are recommended during the acute phase; avoid strenuous exercise until symptom-free. Prevent recurrence/worsening by enforcing temporary exertion limits.', 'Pericarditis - NCLEX', false, 18, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Second-line steroids" in Pericarditis?', 'In rapid prioritization, which statement is most consistent with "Second-line steroids" in Pericarditis?', '[{"id": "a", "text": "SLE-related pericarditis should avoid steroids."}, {"id": "b", "text": "Routine anticoagulation is first-line Dressler treatment."}, {"id": "c", "text": "Specific etiologies (e.g., SLE) can justify steroid use."}, {"id": "d", "text": "Steroids are mandatory first-line for all cases."}]'::jsonb, '["c"]'::jsonb, 'Correct because Corticosteroids are reserved when NSAID/colchicine fails or for specific causes like SLE. Use steroids selectively to avoid unnecessary exposure and recurrence risk concerns.', 'Pericarditis - NCLEX', false, 19, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Cause-specific caveats" in Pericarditis would the nurse recognize as correct?', 'Which conclusion about "Cause-specific caveats" in Pericarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Triage can ignore EKG in chest pain with suspected pericarditis."}, {"id": "b", "text": "Adapt treatment to etiology instead of one-size-fits-all prescribing."}, {"id": "c", "text": "The best approach is to defer EKG differentiation until outpatient review."}, {"id": "d", "text": "All causes are treated identically with NSAID monotherapy."}]'::jsonb, '["b"]'::jsonb, 'Correct because Avoid NSAIDs in uremic pericarditis; use IV antibiotics for bacterial causes and anti-TB therapy for TB. Adapt treatment to etiology instead of one-size-fits-all prescribing.', 'Pericarditis - NCLEX', false, 20, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pericarditis note, which statement about "Tamponade emergency bridge" is most accurate?', 'According to the Pericarditis note, which statement about "Tamponade emergency bridge" is most accurate?', '[{"id": "a", "text": "Reciprocal ST depression is a hallmark of pericarditis."}, {"id": "b", "text": "Localized-only ST elevation is required for diagnosis."}, {"id": "c", "text": "Tamponade in pericarditis is managed with observation only."}, {"id": "d", "text": "Emergency pericardiocentesis is required for tamponade."}]'::jsonb, '["d"]'::jsonb, 'Correct because Tamponade complication is identified by Beck triad and treated with emergency pericardiocentesis. Escalate immediately when hypotension + JVD + muffled tones develop.', 'Pericarditis - NCLEX', false, 21, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Dressler management caveat" in Pericarditis. Which statement is correct?', 'The nurse is reviewing "Dressler management caveat" in Pericarditis. Which statement is correct?', '[{"id": "a", "text": "Pericarditis is confined to coronary arteries."}, {"id": "b", "text": "Dressler syndrome occurs immediately during MI."}, {"id": "c", "text": "Routine anticoagulation is first-line Dressler treatment."}, {"id": "d", "text": "NSAID plus colchicine is recommended for Dressler syndrome."}]'::jsonb, '["d"]'::jsonb, 'Correct because Dressler syndrome is treated with NSAIDs + colchicine and anticoagulants are avoided due to bleeding risk into pericardium. Prevent iatrogenic hemopericardium by avoiding anticoagulants in this context.', 'Pericarditis - NCLEX', false, 22, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "NCLEX triage anchor" in Pericarditis?', 'Which clinical judgment is most accurate regarding "NCLEX triage anchor" in Pericarditis?', '[{"id": "a", "text": "Tamponade surveillance is unnecessary in pericarditis."}, {"id": "b", "text": "Pericarditis is always single-episode and never recurrent."}, {"id": "c", "text": "Constrictive disease is unrelated to pericarditis."}, {"id": "d", "text": "Pain pattern and position response are triage anchors."}]'::jsonb, '["d"]'::jsonb, 'Correct because In suspected pericarditis, prioritize pain pattern recognition, friction rub assessment, EKG interpretation, and tamponade surveillance. Rapid differentiation from MI and early complication detection guide safe outcomes.', 'Pericarditis - NCLEX', false, 23, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Hallmark synthesis" in Pericarditis?', 'In rapid prioritization, which statement is most consistent with "Hallmark synthesis" in Pericarditis?', '[{"id": "a", "text": "Diffuse ST elevation with PR depression supports diagnosis."}, {"id": "b", "text": "The best approach is to defer EKG differentiation until outpatient review."}, {"id": "c", "text": "Reciprocal ST depression is a hallmark of pericarditis."}, {"id": "d", "text": "Localized-only ST elevation is required for diagnosis."}]'::jsonb, '["a"]'::jsonb, 'Correct because Core hallmarks are pleuritic positional chest pain, friction rub, diffuse ST elevation, PR depression, and absent reciprocal ST changes. Synthesize multi-domain clues rather than relying on one isolated finding.', 'Pericarditis - NCLEX', false, 24, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Definition" in Pericarditis would the nurse recognize as correct?', 'Which conclusion about "Definition" in Pericarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Pericarditis is confined to coronary arteries."}, {"id": "b", "text": "Pericarditis is inflammation of heart valves."}, {"id": "c", "text": "Inflammation can progress to pericardial effusion."}, {"id": "d", "text": "Friction rub is a definitive MI finding."}]'::jsonb, '["c"]'::jsonb, 'Correct because Pericarditis is inflammation of the pericardium, the fibrous sac surrounding the heart. Identify inflammatory pericardial pain patterns early to prevent complications.', 'Pericarditis - NCLEX', false, 25, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pericarditis note, which statement about "Disease course" is most accurate?', 'According to the Pericarditis note, which statement about "Disease course" is most accurate?', '[{"id": "a", "text": "Recurrent patterns require recurrence-prevention therapy and follow-up."}, {"id": "b", "text": "Immediate escalation is unnecessary because complication risk is negligible."}, {"id": "c", "text": "Pericarditis is always single-episode and never recurrent."}, {"id": "d", "text": "The best approach is to defer EKG differentiation until outpatient review."}]'::jsonb, '["a"]'::jsonb, 'Correct because Pericarditis can be acute, recurrent, or chronic constrictive. Recurrent patterns require recurrence-prevention therapy and follow-up.', 'Pericarditis - NCLEX', false, 26, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Effusion complication" in Pericarditis. Which statement is correct?', 'The nurse is reviewing "Effusion complication" in Pericarditis. Which statement is correct?', '[{"id": "a", "text": "ST elevation is absent in pericarditis."}, {"id": "b", "text": "Large effusions can compress the heart."}, {"id": "c", "text": "Dressler syndrome is bacterial endocarditis."}, {"id": "d", "text": "Tamponade is a harmless expected phase."}]'::jsonb, '["b"]'::jsonb, 'Correct because Fluid accumulation can cause pericardial effusion, and large effusions can lead to cardiac tamponade. Escalate promptly when effusion signs appear because tamponade is life-threatening.', 'Pericarditis - NCLEX', false, 27, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Common causes" in Pericarditis?', 'Which clinical judgment is most accurate regarding "Common causes" in Pericarditis?', '[{"id": "a", "text": "Prioritize broad etiologic review while managing inflammation and pain."}, {"id": "b", "text": "The best approach is to defer EKG differentiation until outpatient review."}, {"id": "c", "text": "Immediate escalation is unnecessary because complication risk is negligible."}, {"id": "d", "text": "Pericarditis is almost never viral."}]'::jsonb, '["a"]'::jsonb, 'Correct because Viral causes are most common, and many cases are idiopathic. Prioritize broad etiologic review while managing inflammation and pain.', 'Pericarditis - NCLEX', false, 28, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Systemic/infectious causes" in Pericarditis?', 'In rapid prioritization, which statement is most consistent with "Systemic/infectious causes" in Pericarditis?', '[{"id": "a", "text": "Tailor treatment to the underlying cause while controlling inflammation."}, {"id": "b", "text": "Immediate escalation is unnecessary because complication risk is negligible."}, {"id": "c", "text": "The best approach is to defer EKG differentiation until outpatient review."}, {"id": "d", "text": "Pericarditis is unrelated to renal failure."}]'::jsonb, '["a"]'::jsonb, 'Correct because Bacterial TB/S. aureus, autoimmune disease, uremia, malignancy, radiation, trauma, surgery, and medications are listed causes. Tailor treatment to the underlying cause while controlling inflammation.', 'Pericarditis - NCLEX', false, 29, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Dressler syndrome timing" in Pericarditis would the nurse recognize as correct?', 'Which conclusion about "Dressler syndrome timing" in Pericarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Rub is best heard at the carotids."}, {"id": "b", "text": "Cardiac surgery is another trigger."}, {"id": "c", "text": "Dressler syndrome is bacterial endocarditis."}, {"id": "d", "text": "Electrical alternans excludes effusion."}]'::jsonb, '["b"]'::jsonb, 'Correct because Dressler syndrome is autoimmune pericarditis occurring 1–6 weeks after MI or cardiac surgery. Recognize delayed post-MI/surgical chest pain as possible Dressler syndrome.', 'Pericarditis - NCLEX', false, 30, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pericarditis note, which statement about "Classic pain profile" is most accurate?', 'According to the Pericarditis note, which statement about "Classic pain profile" is most accurate?', '[{"id": "a", "text": "Pain is position-independent pressure pain."}, {"id": "b", "text": "Pericarditis pain is sharp/pleuritic, worse with inspiration and lying flat, and relieved by sitting up/leaning forward."}, {"id": "c", "text": "The best approach is to defer EKG differentiation until outpatient review."}, {"id": "d", "text": "Immediate escalation is unnecessary because complication risk is negligible."}]'::jsonb, '["b"]'::jsonb, 'Correct because Pericarditis pain is sharp/pleuritic, worse with inspiration and lying flat, and relieved by sitting up/leaning forward. Use positional and pleuritic features to distinguish from ischemic chest pain patterns.', 'Pericarditis - NCLEX', false, 31, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Radiation and associated symptoms" in Pericarditis. Which statement is correct?', 'The nurse is reviewing "Radiation and associated symptoms" in Pericarditis. Which statement is correct?', '[{"id": "a", "text": "Pericarditis causes only contiguous territorial ST elevation."}, {"id": "b", "text": "Viral-associated constitutional symptoms may occur."}, {"id": "c", "text": "Trapezius radiation excludes pericarditis."}, {"id": "d", "text": "Troponin is never elevated in any pericarditis scenario."}]'::jsonb, '["b"]'::jsonb, 'Correct because Pain can radiate to left shoulder/trapezius; fever, malaise, myalgia, and dyspnea can occur. Link systemic symptoms with inflammatory etiology during triage.', 'Pericarditis - NCLEX', false, 32, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Friction rub hallmark" in Pericarditis?', 'Which clinical judgment is most accurate regarding "Friction rub hallmark" in Pericarditis?', '[{"id": "a", "text": "Friction rub is a definitive MI finding."}, {"id": "b", "text": "The best approach is to defer EKG differentiation until outpatient review."}, {"id": "c", "text": "Prioritize focused auscultation technique to capture fleeting rub findings."}, {"id": "d", "text": "Immediate escalation is unnecessary because complication risk is negligible."}]'::jsonb, '["c"]'::jsonb, 'Correct because Pericardial friction rub is pathognomonic: high-pitched scratchy/grating, best heard at left sternal border with patient leaning forward. Prioritize focused auscultation technique to capture fleeting rub findings.', 'Pericarditis - NCLEX', false, 33, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Rub nuances" in Pericarditis?', 'In rapid prioritization, which statement is most consistent with "Rub nuances" in Pericarditis?', '[{"id": "a", "text": "Reciprocal changes have no differential value."}, {"id": "b", "text": "Persistent rub is required throughout all stages."}, {"id": "c", "text": "High-intensity exercise accelerates recovery."}, {"id": "d", "text": "Rub can disappear when effusion increases."}]'::jsonb, '["d"]'::jsonb, 'Correct because The rub may be triphasic and can disappear if effusion develops as fluid separates pericardial layers. Do not rule out pericarditis solely because rub is absent later in disease.', 'Pericarditis - NCLEX', false, 34, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Diffuse ST elevation" in Pericarditis would the nurse recognize as correct?', 'Which conclusion about "Diffuse ST elevation" in Pericarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Steroids are mandatory first-line for all cases."}, {"id": "b", "text": "SLE-related pericarditis should avoid steroids."}, {"id": "c", "text": "Pericarditis causes only contiguous territorial ST elevation."}, {"id": "d", "text": "This pattern differs from localized MI territories."}]'::jsonb, '["d"]'::jsonb, 'Correct because Pericarditis classically shows diffuse (all-lead) saddle-shaped ST elevation. Differentiate diffuse inflammatory ST elevation from territorial ischemic patterns.', 'Pericarditis - NCLEX', false, 35, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pericarditis note, which statement about "PR depression" is most accurate?', 'According to the Pericarditis note, which statement about "PR depression" is most accurate?', '[{"id": "a", "text": "PR elevation is the classic early finding."}, {"id": "b", "text": "It appears early in the disease course."}, {"id": "c", "text": "MI pain improves when leaning forward."}, {"id": "d", "text": "PR changes are irrelevant in pericarditis."}]'::jsonb, '["b"]'::jsonb, 'Correct because PR depression is a classic early pericarditis finding and opposite ST direction. Use PR deviation as a high-yield discriminator in early interpretation.', 'Pericarditis - NCLEX', false, 36, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "No reciprocal changes" in Pericarditis. Which statement is correct?', 'The nurse is reviewing "No reciprocal changes" in Pericarditis. Which statement is correct?', '[{"id": "a", "text": "Pericarditis requires reciprocal ST depression."}, {"id": "b", "text": "Tamponade in pericarditis is managed with observation only."}, {"id": "c", "text": "Troponin is never elevated in any pericarditis scenario."}, {"id": "d", "text": "Reciprocal changes support MI rather than pericarditis."}]'::jsonb, '["d"]'::jsonb, 'Correct because Pericarditis has no reciprocal ST depression, unlike MI. Avoid mislabeling diffuse pericarditis as STEMI when reciprocal changes are absent.', 'Pericarditis - NCLEX', false, 37, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Later EKG evolution" in Pericarditis?', 'Which clinical judgment is most accurate regarding "Later EKG evolution" in Pericarditis?', '[{"id": "a", "text": "Opioids are listed as definitive first-line therapy."}, {"id": "b", "text": "EKG pattern is fixed and never evolves."}, {"id": "c", "text": "EKG pattern evolves over time in pericarditis."}, {"id": "d", "text": "Colchicine is contraindicated in all pericarditis."}]'::jsonb, '["c"]'::jsonb, 'Correct because T-wave inversion may appear in later stages; electrical alternans can appear with large effusion. Interpret EKG changes in temporal context and effusion severity.', 'Pericarditis - NCLEX', false, 38, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Pericarditis vs MI pain differences" in Pericarditis?', 'In rapid prioritization, which statement is most consistent with "Pericarditis vs MI pain differences" in Pericarditis?', '[{"id": "a", "text": "No activity limits are needed during acute phase."}, {"id": "b", "text": "MI pain improves when leaning forward."}, {"id": "c", "text": "High-intensity exercise accelerates recovery."}, {"id": "d", "text": "MI pain is generally not position-dependent."}]'::jsonb, '["d"]'::jsonb, 'Correct because Pericarditis pain is gradual, sharp, pleuritic, and positional; MI pain is sudden, crushing, pressure-like, and non-positional. Use symptom quality and positional response to sharpen early triage decisions.', 'Pericarditis - NCLEX', false, 39, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Pericarditis vs MI EKG/lab clues" in Pericarditis would the nurse recognize as correct?', 'Which conclusion about "Pericarditis vs MI EKG/lab clues" in Pericarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Diffuse ST elevation with PR depression supports pericarditis."}, {"id": "b", "text": "Localized-only ST elevation is required for diagnosis."}, {"id": "c", "text": "Reciprocal ST depression is a hallmark of pericarditis."}, {"id": "d", "text": "Troponin is never elevated in any pericarditis scenario."}]'::jsonb, '["a"]'::jsonb, 'Correct because Pericarditis: diffuse ST elevation + PR depression + absent Q waves; MI: localized ST elevation, reciprocal changes, Q waves in STEMI, higher troponin rise. Integrate EKG with biomarker pattern to avoid anchoring errors.', 'Pericarditis - NCLEX', false, 40, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pericarditis note, which statement about "First-line therapy" is most accurate?', 'According to the Pericarditis note, which statement about "First-line therapy" is most accurate?', '[{"id": "a", "text": "Start anti-inflammatory therapy early and include recurrence prevention."}, {"id": "b", "text": "Immediate escalation is unnecessary because complication risk is negligible."}, {"id": "c", "text": "Opioids are listed as definitive first-line therapy."}, {"id": "d", "text": "The best approach is to defer EKG differentiation until outpatient review."}]'::jsonb, '["a"]'::jsonb, 'Correct because First-line treatment is NSAIDs (ibuprofen/aspirin) plus colchicine to reduce recurrence risk. Start anti-inflammatory therapy early and include recurrence prevention.', 'Pericarditis - NCLEX', false, 41, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Activity guidance" in Pericarditis. Which statement is correct?', 'The nurse is reviewing "Activity guidance" in Pericarditis. Which statement is correct?', '[{"id": "a", "text": "Constrictive disease is unrelated to pericarditis."}, {"id": "b", "text": "No activity limits are needed during acute phase."}, {"id": "c", "text": "High-intensity exercise accelerates recovery."}, {"id": "d", "text": "Rest is recommended in acute pericarditis."}]'::jsonb, '["d"]'::jsonb, 'Correct because Rest and activity restriction are recommended during the acute phase; avoid strenuous exercise until symptom-free. Prevent recurrence/worsening by enforcing temporary exertion limits.', 'Pericarditis - NCLEX', false, 42, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Second-line steroids" in Pericarditis?', 'Which clinical judgment is most accurate regarding "Second-line steroids" in Pericarditis?', '[{"id": "a", "text": "Routine anticoagulation is first-line Dressler treatment."}, {"id": "b", "text": "Steroids are mandatory first-line for all cases."}, {"id": "c", "text": "SLE-related pericarditis should avoid steroids."}, {"id": "d", "text": "Steroids are considered when first-line therapy fails."}]'::jsonb, '["d"]'::jsonb, 'Correct because Corticosteroids are reserved when NSAID/colchicine fails or for specific causes like SLE. Use steroids selectively to avoid unnecessary exposure and recurrence risk concerns.', 'Pericarditis - NCLEX', false, 43, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Cause-specific caveats" in Pericarditis?', 'In rapid prioritization, which statement is most consistent with "Cause-specific caveats" in Pericarditis?', '[{"id": "a", "text": "All causes are treated identically with NSAID monotherapy."}, {"id": "b", "text": "Triage can ignore EKG in chest pain with suspected pericarditis."}, {"id": "c", "text": "Adapt treatment to etiology instead of one-size-fits-all prescribing."}, {"id": "d", "text": "The best approach is to defer EKG differentiation until outpatient review."}]'::jsonb, '["c"]'::jsonb, 'Correct because Avoid NSAIDs in uremic pericarditis; use IV antibiotics for bacterial causes and anti-TB therapy for TB. Adapt treatment to etiology instead of one-size-fits-all prescribing.', 'Pericarditis - NCLEX', false, 44, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Tamponade emergency bridge" in Pericarditis would the nurse recognize as correct?', 'Which conclusion about "Tamponade emergency bridge" in Pericarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Immediate escalation is unnecessary because complication risk is negligible."}, {"id": "b", "text": "Escalate immediately when hypotension + JVD + muffled tones develop."}, {"id": "c", "text": "The best approach is to defer EKG differentiation until outpatient review."}, {"id": "d", "text": "Tamponade in pericarditis is managed with observation only."}]'::jsonb, '["b"]'::jsonb, 'Correct because Tamponade complication is identified by Beck triad and treated with emergency pericardiocentesis. Escalate immediately when hypotension + JVD + muffled tones develop.', 'Pericarditis - NCLEX', false, 45, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Pericarditis note, which statement about "Dressler management caveat" is most accurate?', 'According to the Pericarditis note, which statement about "Dressler management caveat" is most accurate?', '[{"id": "a", "text": "Anticoagulants are avoided because of pericardial bleeding risk."}, {"id": "b", "text": "Routine anticoagulation is first-line Dressler treatment."}, {"id": "c", "text": "Immediate escalation is unnecessary because complication risk is negligible."}, {"id": "d", "text": "The best approach is to defer EKG differentiation until outpatient review."}]'::jsonb, '["a"]'::jsonb, 'Correct because Dressler syndrome is treated with NSAIDs + colchicine and anticoagulants are avoided due to bleeding risk into pericardium. Prevent iatrogenic hemopericardium by avoiding anticoagulants in this context.', 'Pericarditis - NCLEX', false, 46, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "NCLEX triage anchor" in Pericarditis. Which statement is correct?', 'The nurse is reviewing "NCLEX triage anchor" in Pericarditis. Which statement is correct?', '[{"id": "a", "text": "Constrictive disease is unrelated to pericarditis."}, {"id": "b", "text": "Tamponade surveillance is unnecessary in pericarditis."}, {"id": "c", "text": "Pericarditis is always single-episode and never recurrent."}, {"id": "d", "text": "Friction rub and EKG clues are high-yield assessments."}]'::jsonb, '["d"]'::jsonb, 'Correct because In suspected pericarditis, prioritize pain pattern recognition, friction rub assessment, EKG interpretation, and tamponade surveillance. Rapid differentiation from MI and early complication detection guide safe outcomes.', 'Pericarditis - NCLEX', false, 47, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Hallmark synthesis" in Pericarditis?', 'Which clinical judgment is most accurate regarding "Hallmark synthesis" in Pericarditis?', '[{"id": "a", "text": "Tamponade is a harmless expected phase."}, {"id": "b", "text": "Localized-only ST elevation is required for diagnosis."}, {"id": "c", "text": "Trapezius radiation excludes pericarditis."}, {"id": "d", "text": "Pleuritic positional pain is a hallmark."}]'::jsonb, '["d"]'::jsonb, 'Correct because Core hallmarks are pleuritic positional chest pain, friction rub, diffuse ST elevation, PR depression, and absent reciprocal ST changes. Synthesize multi-domain clues rather than relying on one isolated finding.', 'Pericarditis - NCLEX', false, 48, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Definition" in Pericarditis?', 'In rapid prioritization, which statement is most consistent with "Definition" in Pericarditis?', '[{"id": "a", "text": "Friction rub is a definitive MI finding."}, {"id": "b", "text": "Pericarditis is confined to coronary arteries."}, {"id": "c", "text": "Pericarditis is inflammation of heart valves."}, {"id": "d", "text": "The pericardium is the sac around the heart."}]'::jsonb, '["d"]'::jsonb, 'Correct because Pericarditis is inflammation of the pericardium, the fibrous sac surrounding the heart. Identify inflammatory pericardial pain patterns early to prevent complications.', 'Pericarditis - NCLEX', false, 49, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Disease course" in Pericarditis would the nurse recognize as correct?', 'Which conclusion about "Disease course" in Pericarditis would the nurse recognize as correct?', '[{"id": "a", "text": "Pericarditis can be acute, recurrent, or chronic constrictive."}, {"id": "b", "text": "Pericarditis is always single-episode and never recurrent."}, {"id": "c", "text": "The best approach is to defer EKG differentiation until outpatient review."}, {"id": "d", "text": "Constrictive disease is unrelated to pericarditis."}]'::jsonb, '["a"]'::jsonb, 'Correct because Pericarditis can be acute, recurrent, or chronic constrictive. Recurrent patterns require recurrence-prevention therapy and follow-up.', 'Pericarditis - NCLEX', false, 50, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Definition" in Pericarditis are correct? (Select all that apply)', 'Which statements about "Definition" in Pericarditis are correct? (Select all that apply)', '[{"id": "a", "text": "Pericarditis is inflammation of heart valves."}, {"id": "b", "text": "Pericarditis involves inflammation of pericardial layers."}, {"id": "c", "text": "Pericarditis is confined to coronary arteries."}, {"id": "d", "text": "The pericardium is the sac around the heart."}, {"id": "e", "text": "Inflammation can progress to pericardial effusion."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis is inflammation of the pericardium, the fibrous sac surrounding the heart.', 'Pericarditis - NCLEX', true, 51, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pericarditis, which findings or actions relate to "Disease course"? (Select all that apply)', 'For Pericarditis, which findings or actions relate to "Disease course"? (Select all that apply)', '[{"id": "a", "text": "Recurrent forms are described."}, {"id": "b", "text": "Pericarditis is always single-episode and never recurrent."}, {"id": "c", "text": "Chronic constrictive forms are also listed."}, {"id": "d", "text": "Acute forms are described."}, {"id": "e", "text": "Constrictive disease is unrelated to pericarditis."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis can be acute, recurrent, or chronic constrictive.', 'Pericarditis - NCLEX', true, 52, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Effusion complication" in Pericarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "Effusion complication" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Large effusions can compress the heart."}, {"id": "b", "text": "Tamponade is a life-threatening pericarditis complication."}, {"id": "c", "text": "Pericardial inflammation can produce effusion."}, {"id": "d", "text": "Effusion improves cardiac filling."}, {"id": "e", "text": "Tamponade is a harmless expected phase."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Fluid accumulation can cause pericardial effusion, and large effusions can lead to cardiac tamponade.', 'Pericarditis - NCLEX', true, 53, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Common causes" in Pericarditis? (Select all that apply)', 'Which of the following are consistent with "Common causes" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Viral etiologies are highlighted as most common."}, {"id": "b", "text": "Idiopathic cases are frequent."}, {"id": "c", "text": "Idiopathic causes are excluded."}, {"id": "d", "text": "Coxsackievirus/Echovirus/Influenza are listed viral examples."}, {"id": "e", "text": "Pericarditis is almost never viral."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Viral causes are most common, and many cases are idiopathic.', 'Pericarditis - NCLEX', true, 54, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Systemic/infectious causes" in Pericarditis? (Select all that apply)', 'During reassessment, which observations align with "Systemic/infectious causes" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "SLE/RA/scleroderma are autoimmune causes."}, {"id": "b", "text": "Hydralazine and Procainamide are listed medication causes."}, {"id": "c", "text": "TB and S. aureus are listed infectious causes."}, {"id": "d", "text": "Pericarditis is unrelated to renal failure."}, {"id": "e", "text": "Radiation cannot cause pericarditis."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Bacterial TB/S. aureus, autoimmune disease, uremia, malignancy, radiation, trauma, surgery, and medications are listed causes.', 'Pericarditis - NCLEX', true, 55, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Dressler syndrome timing" in Pericarditis are correct? (Select all that apply)', 'Which statements about "Dressler syndrome timing" in Pericarditis are correct? (Select all that apply)', '[{"id": "a", "text": "Cardiac surgery is another trigger."}, {"id": "b", "text": "Timing is listed as 1–6 weeks post-event."}, {"id": "c", "text": "Dressler syndrome is bacterial endocarditis."}, {"id": "d", "text": "Dressler syndrome occurs immediately during MI."}, {"id": "e", "text": "Dressler syndrome can occur after MI."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Dressler syndrome is autoimmune pericarditis occurring 1–6 weeks after MI or cardiac surgery.', 'Pericarditis - NCLEX', true, 56, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pericarditis, which findings or actions relate to "Classic pain profile"? (Select all that apply)', 'For Pericarditis, which findings or actions relate to "Classic pain profile"? (Select all that apply)', '[{"id": "a", "text": "Pain worsens with inspiration."}, {"id": "b", "text": "Leaning forward worsens pain."}, {"id": "c", "text": "Pain is position-independent pressure pain."}, {"id": "d", "text": "Leaning forward provides relief."}, {"id": "e", "text": "Pain worsens when lying flat."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis pain is sharp/pleuritic, worse with inspiration and lying flat, and relieved by sitting up/leaning forward.', 'Pericarditis - NCLEX', true, 57, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Radiation and associated symptoms" in Pericarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "Radiation and associated symptoms" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Viral-associated constitutional symptoms may occur."}, {"id": "b", "text": "Left shoulder/trapezius radiation is described."}, {"id": "c", "text": "Dyspnea never occurs in pericarditis."}, {"id": "d", "text": "Trapezius radiation excludes pericarditis."}, {"id": "e", "text": "Dyspnea can accompany pericarditis."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Pain can radiate to left shoulder/trapezius; fever, malaise, myalgia, and dyspnea can occur.', 'Pericarditis - NCLEX', true, 58, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Friction rub hallmark" in Pericarditis? (Select all that apply)', 'Which of the following are consistent with "Friction rub hallmark" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "The rub is described as high-pitched scratchy/grating."}, {"id": "b", "text": "Friction rub is a definitive MI finding."}, {"id": "c", "text": "Best heard at left sternal border while leaning forward."}, {"id": "d", "text": "Friction rub is pathognomonic."}, {"id": "e", "text": "Rub is best heard at the carotids."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Pericardial friction rub is pathognomonic: high-pitched scratchy/grating, best heard at left sternal border with patient leaning forward.', 'Pericarditis - NCLEX', true, 59, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Rub nuances" in Pericarditis? (Select all that apply)', 'During reassessment, which observations align with "Rub nuances" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Triphasic friction rub may be present."}, {"id": "b", "text": "Loss of rub does not exclude worsening complications."}, {"id": "c", "text": "Persistent rub is required throughout all stages."}, {"id": "d", "text": "Rub can disappear when effusion increases."}, {"id": "e", "text": "Effusion makes rub louder by increasing friction."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: The rub may be triphasic and can disappear if effusion develops as fluid separates pericardial layers.', 'Pericarditis - NCLEX', true, 60, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Diffuse ST elevation" in Pericarditis are correct? (Select all that apply)', 'Which statements about "Diffuse ST elevation" in Pericarditis are correct? (Select all that apply)', '[{"id": "a", "text": "This pattern differs from localized MI territories."}, {"id": "b", "text": "Diffuse ST elevation is emphasized."}, {"id": "c", "text": "ST elevation is absent in pericarditis."}, {"id": "d", "text": "Saddle-shaped morphology is associated with pericarditis."}, {"id": "e", "text": "Pericarditis causes only contiguous territorial ST elevation."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis classically shows diffuse (all-lead) saddle-shaped ST elevation.', 'Pericarditis - NCLEX', true, 61, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pericarditis, which findings or actions relate to "PR depression"? (Select all that apply)', 'For Pericarditis, which findings or actions relate to "PR depression"? (Select all that apply)', '[{"id": "a", "text": "PR depression is a classic finding."}, {"id": "b", "text": "PR elevation is the classic early finding."}, {"id": "c", "text": "PR direction contrasts with ST elevation."}, {"id": "d", "text": "PR changes are irrelevant in pericarditis."}, {"id": "e", "text": "It appears early in the disease course."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: PR depression is a classic early pericarditis finding and opposite ST direction.', 'Pericarditis - NCLEX', true, 62, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "No reciprocal changes" in Pericarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "No reciprocal changes" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Reciprocal ST depression is absent in pericarditis."}, {"id": "b", "text": "This distinction is used in pericarditis vs MI comparison."}, {"id": "c", "text": "Reciprocal changes have no differential value."}, {"id": "d", "text": "Pericarditis requires reciprocal ST depression."}, {"id": "e", "text": "Reciprocal changes support MI rather than pericarditis."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis has no reciprocal ST depression, unlike MI.', 'Pericarditis - NCLEX', true, 63, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Later EKG evolution" in Pericarditis? (Select all that apply)', 'Which of the following are consistent with "Later EKG evolution" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "EKG pattern is fixed and never evolves."}, {"id": "b", "text": "EKG pattern evolves over time in pericarditis."}, {"id": "c", "text": "Electrical alternans excludes effusion."}, {"id": "d", "text": "Electrical alternans can accompany large effusion."}, {"id": "e", "text": "T-wave inversion can occur later."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: T-wave inversion may appear in later stages; electrical alternans can appear with large effusion.', 'Pericarditis - NCLEX', true, 64, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Pericarditis vs MI pain differences" in Pericarditis? (Select all that apply)', 'During reassessment, which observations align with "Pericarditis vs MI pain differences" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Pericarditis pain is classically crushing pressure."}, {"id": "b", "text": "MI pain improves when leaning forward."}, {"id": "c", "text": "MI pain is described as pressure-like/crushing."}, {"id": "d", "text": "Pericarditis pain is often pleuritic and positional."}, {"id": "e", "text": "MI pain is generally not position-dependent."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis pain is gradual, sharp, pleuritic, and positional; MI pain is sudden, crushing, pressure-like, and non-positional.', 'Pericarditis - NCLEX', true, 65, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Pericarditis vs MI EKG/lab clues" in Pericarditis are correct? (Select all that apply)', 'Which statements about "Pericarditis vs MI EKG/lab clues" in Pericarditis are correct? (Select all that apply)', '[{"id": "a", "text": "Troponin may be mildly elevated in myopericarditis but higher in MI."}, {"id": "b", "text": "Diffuse ST elevation with PR depression supports pericarditis."}, {"id": "c", "text": "Localized ST elevation with reciprocal changes supports MI."}, {"id": "d", "text": "Q waves are a pericarditis hallmark."}, {"id": "e", "text": "Troponin is never elevated in any pericarditis scenario."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis: diffuse ST elevation + PR depression + absent Q waves; MI: localized ST elevation, reciprocal changes, Q waves in STEMI, higher troponin rise.', 'Pericarditis - NCLEX', true, 66, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pericarditis, which findings or actions relate to "First-line therapy"? (Select all that apply)', 'For Pericarditis, which findings or actions relate to "First-line therapy"? (Select all that apply)', '[{"id": "a", "text": "Colchicine is contraindicated in all pericarditis."}, {"id": "b", "text": "Colchicine is added to reduce recurrence risk."}, {"id": "c", "text": "Combination therapy is emphasized for acute management."}, {"id": "d", "text": "NSAIDs are first-line."}, {"id": "e", "text": "Opioids are listed as definitive first-line therapy."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: First-line treatment is NSAIDs (ibuprofen/aspirin) plus colchicine to reduce recurrence risk.', 'Pericarditis - NCLEX', true, 67, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Activity guidance" in Pericarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "Activity guidance" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Rest is recommended in acute pericarditis."}, {"id": "b", "text": "No activity limits are needed during acute phase."}, {"id": "c", "text": "High-intensity exercise accelerates recovery."}, {"id": "d", "text": "Strenuous exercise should be avoided until symptom-free."}, {"id": "e", "text": "Activity guidance is part of initial management."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Rest and activity restriction are recommended during the acute phase; avoid strenuous exercise until symptom-free.', 'Pericarditis - NCLEX', true, 68, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Second-line steroids" in Pericarditis? (Select all that apply)', 'Which of the following are consistent with "Second-line steroids" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "SLE-related pericarditis should avoid steroids."}, {"id": "b", "text": "Prednisone is not first-line in routine cases."}, {"id": "c", "text": "Steroids are mandatory first-line for all cases."}, {"id": "d", "text": "Steroids are considered when first-line therapy fails."}, {"id": "e", "text": "Specific etiologies (e.g., SLE) can justify steroid use."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Corticosteroids are reserved when NSAID/colchicine fails or for specific causes like SLE.', 'Pericarditis - NCLEX', true, 69, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Cause-specific caveats" in Pericarditis? (Select all that apply)', 'During reassessment, which observations align with "Cause-specific caveats" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "TB pericarditis requires anti-TB therapy."}, {"id": "b", "text": "Bacterial pericarditis requires IV antibiotics."}, {"id": "c", "text": "All causes are treated identically with NSAID monotherapy."}, {"id": "d", "text": "TB management is excluded from pericarditis care."}, {"id": "e", "text": "Uremic pericarditis is a context to avoid NSAIDs."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Avoid NSAIDs in uremic pericarditis; use IV antibiotics for bacterial causes and anti-TB therapy for TB.', 'Pericarditis - NCLEX', true, 70, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Tamponade emergency bridge" in Pericarditis are correct? (Select all that apply)', 'Which statements about "Tamponade emergency bridge" in Pericarditis are correct? (Select all that apply)', '[{"id": "a", "text": "Tamponade is life-threatening."}, {"id": "b", "text": "Beck triad excludes tamponade."}, {"id": "c", "text": "Tamponade in pericarditis is managed with observation only."}, {"id": "d", "text": "Emergency pericardiocentesis is required for tamponade."}, {"id": "e", "text": "Beck triad is listed with tamponade complication."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Tamponade complication is identified by Beck triad and treated with emergency pericardiocentesis.', 'Pericarditis - NCLEX', true, 71, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pericarditis, which findings or actions relate to "Dressler management caveat"? (Select all that apply)', 'For Pericarditis, which findings or actions relate to "Dressler management caveat"? (Select all that apply)', '[{"id": "a", "text": "Routine anticoagulation is first-line Dressler treatment."}, {"id": "b", "text": "Anticoagulants are avoided because of pericardial bleeding risk."}, {"id": "c", "text": "NSAID plus colchicine is recommended for Dressler syndrome."}, {"id": "d", "text": "Dressler is autoimmune and post-MI/surgery."}, {"id": "e", "text": "Dressler treatment excludes NSAIDs."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Dressler syndrome is treated with NSAIDs + colchicine and anticoagulants are avoided due to bleeding risk into pericardium.', 'Pericarditis - NCLEX', true, 72, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "NCLEX triage anchor" in Pericarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "NCLEX triage anchor" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Triage can ignore EKG in chest pain with suspected pericarditis."}, {"id": "b", "text": "Tamponade surveillance is unnecessary in pericarditis."}, {"id": "c", "text": "Monitor for progression to effusion/tamponade."}, {"id": "d", "text": "Pain pattern and position response are triage anchors."}, {"id": "e", "text": "Friction rub and EKG clues are high-yield assessments."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: In suspected pericarditis, prioritize pain pattern recognition, friction rub assessment, EKG interpretation, and tamponade surveillance.', 'Pericarditis - NCLEX', true, 73, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Hallmark synthesis" in Pericarditis? (Select all that apply)', 'Which of the following are consistent with "Hallmark synthesis" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Localized-only ST elevation is required for diagnosis."}, {"id": "b", "text": "Diffuse ST elevation with PR depression supports diagnosis."}, {"id": "c", "text": "Reciprocal ST depression is a hallmark of pericarditis."}, {"id": "d", "text": "Friction rub is a hallmark."}, {"id": "e", "text": "Pleuritic positional pain is a hallmark."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Core hallmarks are pleuritic positional chest pain, friction rub, diffuse ST elevation, PR depression, and absent reciprocal ST changes.', 'Pericarditis - NCLEX', true, 74, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Definition" in Pericarditis? (Select all that apply)', 'During reassessment, which observations align with "Definition" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Inflammation can progress to pericardial effusion."}, {"id": "b", "text": "Pericarditis is confined to coronary arteries."}, {"id": "c", "text": "The pericardium is the sac around the heart."}, {"id": "d", "text": "Pericarditis is inflammation of heart valves."}, {"id": "e", "text": "Pericarditis involves inflammation of pericardial layers."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis is inflammation of the pericardium, the fibrous sac surrounding the heart.', 'Pericarditis - NCLEX', true, 75, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Disease course" in Pericarditis are correct? (Select all that apply)', 'Which statements about "Disease course" in Pericarditis are correct? (Select all that apply)', '[{"id": "a", "text": "Constrictive disease is unrelated to pericarditis."}, {"id": "b", "text": "Acute forms are described."}, {"id": "c", "text": "Chronic constrictive forms are also listed."}, {"id": "d", "text": "Pericarditis is always single-episode and never recurrent."}, {"id": "e", "text": "Recurrent forms are described."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis can be acute, recurrent, or chronic constrictive.', 'Pericarditis - NCLEX', true, 76, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pericarditis, which findings or actions relate to "Effusion complication"? (Select all that apply)', 'For Pericarditis, which findings or actions relate to "Effusion complication"? (Select all that apply)', '[{"id": "a", "text": "Tamponade is a life-threatening pericarditis complication."}, {"id": "b", "text": "Pericardial inflammation can produce effusion."}, {"id": "c", "text": "Large effusions can compress the heart."}, {"id": "d", "text": "Tamponade is a harmless expected phase."}, {"id": "e", "text": "Effusion improves cardiac filling."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Fluid accumulation can cause pericardial effusion, and large effusions can lead to cardiac tamponade.', 'Pericarditis - NCLEX', true, 77, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Common causes" in Pericarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "Common causes" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Pericarditis is almost never viral."}, {"id": "b", "text": "Idiopathic cases are frequent."}, {"id": "c", "text": "Coxsackievirus/Echovirus/Influenza are listed viral examples."}, {"id": "d", "text": "Viral etiologies are highlighted as most common."}, {"id": "e", "text": "Idiopathic causes are excluded."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Viral causes are most common, and many cases are idiopathic.', 'Pericarditis - NCLEX', true, 78, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Systemic/infectious causes" in Pericarditis? (Select all that apply)', 'Which of the following are consistent with "Systemic/infectious causes" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Hydralazine and Procainamide are listed medication causes."}, {"id": "b", "text": "TB and S. aureus are listed infectious causes."}, {"id": "c", "text": "SLE/RA/scleroderma are autoimmune causes."}, {"id": "d", "text": "Radiation cannot cause pericarditis."}, {"id": "e", "text": "Pericarditis is unrelated to renal failure."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Bacterial TB/S. aureus, autoimmune disease, uremia, malignancy, radiation, trauma, surgery, and medications are listed causes.', 'Pericarditis - NCLEX', true, 79, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Dressler syndrome timing" in Pericarditis? (Select all that apply)', 'During reassessment, which observations align with "Dressler syndrome timing" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Timing is listed as 1–6 weeks post-event."}, {"id": "b", "text": "Cardiac surgery is another trigger."}, {"id": "c", "text": "Dressler syndrome occurs immediately during MI."}, {"id": "d", "text": "Dressler syndrome can occur after MI."}, {"id": "e", "text": "Dressler syndrome is bacterial endocarditis."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Dressler syndrome is autoimmune pericarditis occurring 1–6 weeks after MI or cardiac surgery.', 'Pericarditis - NCLEX', true, 80, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Classic pain profile" in Pericarditis are correct? (Select all that apply)', 'Which statements about "Classic pain profile" in Pericarditis are correct? (Select all that apply)', '[{"id": "a", "text": "Pain worsens when lying flat."}, {"id": "b", "text": "Leaning forward provides relief."}, {"id": "c", "text": "Leaning forward worsens pain."}, {"id": "d", "text": "Pain is position-independent pressure pain."}, {"id": "e", "text": "Pain worsens with inspiration."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis pain is sharp/pleuritic, worse with inspiration and lying flat, and relieved by sitting up/leaning forward.', 'Pericarditis - NCLEX', true, 81, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pericarditis, which findings or actions relate to "Radiation and associated symptoms"? (Select all that apply)', 'For Pericarditis, which findings or actions relate to "Radiation and associated symptoms"? (Select all that apply)', '[{"id": "a", "text": "Dyspnea can accompany pericarditis."}, {"id": "b", "text": "Dyspnea never occurs in pericarditis."}, {"id": "c", "text": "Trapezius radiation excludes pericarditis."}, {"id": "d", "text": "Viral-associated constitutional symptoms may occur."}, {"id": "e", "text": "Left shoulder/trapezius radiation is described."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Pain can radiate to left shoulder/trapezius; fever, malaise, myalgia, and dyspnea can occur.', 'Pericarditis - NCLEX', true, 82, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Friction rub hallmark" in Pericarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "Friction rub hallmark" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Rub is best heard at the carotids."}, {"id": "b", "text": "The rub is described as high-pitched scratchy/grating."}, {"id": "c", "text": "Best heard at left sternal border while leaning forward."}, {"id": "d", "text": "Friction rub is pathognomonic."}, {"id": "e", "text": "Friction rub is a definitive MI finding."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Pericardial friction rub is pathognomonic: high-pitched scratchy/grating, best heard at left sternal border with patient leaning forward.', 'Pericarditis - NCLEX', true, 83, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Rub nuances" in Pericarditis? (Select all that apply)', 'Which of the following are consistent with "Rub nuances" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Triphasic friction rub may be present."}, {"id": "b", "text": "Effusion makes rub louder by increasing friction."}, {"id": "c", "text": "Persistent rub is required throughout all stages."}, {"id": "d", "text": "Loss of rub does not exclude worsening complications."}, {"id": "e", "text": "Rub can disappear when effusion increases."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: The rub may be triphasic and can disappear if effusion develops as fluid separates pericardial layers.', 'Pericarditis - NCLEX', true, 84, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Diffuse ST elevation" in Pericarditis? (Select all that apply)', 'During reassessment, which observations align with "Diffuse ST elevation" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "This pattern differs from localized MI territories."}, {"id": "b", "text": "Saddle-shaped morphology is associated with pericarditis."}, {"id": "c", "text": "Diffuse ST elevation is emphasized."}, {"id": "d", "text": "Pericarditis causes only contiguous territorial ST elevation."}, {"id": "e", "text": "ST elevation is absent in pericarditis."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis classically shows diffuse (all-lead) saddle-shaped ST elevation.', 'Pericarditis - NCLEX', true, 85, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "PR depression" in Pericarditis are correct? (Select all that apply)', 'Which statements about "PR depression" in Pericarditis are correct? (Select all that apply)', '[{"id": "a", "text": "It appears early in the disease course."}, {"id": "b", "text": "PR changes are irrelevant in pericarditis."}, {"id": "c", "text": "PR direction contrasts with ST elevation."}, {"id": "d", "text": "PR elevation is the classic early finding."}, {"id": "e", "text": "PR depression is a classic finding."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: PR depression is a classic early pericarditis finding and opposite ST direction.', 'Pericarditis - NCLEX', true, 86, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pericarditis, which findings or actions relate to "No reciprocal changes"? (Select all that apply)', 'For Pericarditis, which findings or actions relate to "No reciprocal changes"? (Select all that apply)', '[{"id": "a", "text": "Reciprocal changes support MI rather than pericarditis."}, {"id": "b", "text": "This distinction is used in pericarditis vs MI comparison."}, {"id": "c", "text": "Reciprocal changes have no differential value."}, {"id": "d", "text": "Reciprocal ST depression is absent in pericarditis."}, {"id": "e", "text": "Pericarditis requires reciprocal ST depression."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis has no reciprocal ST depression, unlike MI.', 'Pericarditis - NCLEX', true, 87, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Later EKG evolution" in Pericarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "Later EKG evolution" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "T-wave inversion can occur later."}, {"id": "b", "text": "EKG pattern evolves over time in pericarditis."}, {"id": "c", "text": "Electrical alternans excludes effusion."}, {"id": "d", "text": "EKG pattern is fixed and never evolves."}, {"id": "e", "text": "Electrical alternans can accompany large effusion."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: T-wave inversion may appear in later stages; electrical alternans can appear with large effusion.', 'Pericarditis - NCLEX', true, 88, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Pericarditis vs MI pain differences" in Pericarditis? (Select all that apply)', 'Which of the following are consistent with "Pericarditis vs MI pain differences" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Pericarditis pain is often pleuritic and positional."}, {"id": "b", "text": "MI pain is described as pressure-like/crushing."}, {"id": "c", "text": "Pericarditis pain is classically crushing pressure."}, {"id": "d", "text": "MI pain is generally not position-dependent."}, {"id": "e", "text": "MI pain improves when leaning forward."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis pain is gradual, sharp, pleuritic, and positional; MI pain is sudden, crushing, pressure-like, and non-positional.', 'Pericarditis - NCLEX', true, 89, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Pericarditis vs MI EKG/lab clues" in Pericarditis? (Select all that apply)', 'During reassessment, which observations align with "Pericarditis vs MI EKG/lab clues" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Troponin may be mildly elevated in myopericarditis but higher in MI."}, {"id": "b", "text": "Diffuse ST elevation with PR depression supports pericarditis."}, {"id": "c", "text": "Q waves are a pericarditis hallmark."}, {"id": "d", "text": "Troponin is never elevated in any pericarditis scenario."}, {"id": "e", "text": "Localized ST elevation with reciprocal changes supports MI."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis: diffuse ST elevation + PR depression + absent Q waves; MI: localized ST elevation, reciprocal changes, Q waves in STEMI, higher troponin rise.', 'Pericarditis - NCLEX', true, 90, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "First-line therapy" in Pericarditis are correct? (Select all that apply)', 'Which statements about "First-line therapy" in Pericarditis are correct? (Select all that apply)', '[{"id": "a", "text": "Opioids are listed as definitive first-line therapy."}, {"id": "b", "text": "Combination therapy is emphasized for acute management."}, {"id": "c", "text": "NSAIDs are first-line."}, {"id": "d", "text": "Colchicine is added to reduce recurrence risk."}, {"id": "e", "text": "Colchicine is contraindicated in all pericarditis."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: First-line treatment is NSAIDs (ibuprofen/aspirin) plus colchicine to reduce recurrence risk.', 'Pericarditis - NCLEX', true, 91, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pericarditis, which findings or actions relate to "Activity guidance"? (Select all that apply)', 'For Pericarditis, which findings or actions relate to "Activity guidance"? (Select all that apply)', '[{"id": "a", "text": "Rest is recommended in acute pericarditis."}, {"id": "b", "text": "Strenuous exercise should be avoided until symptom-free."}, {"id": "c", "text": "High-intensity exercise accelerates recovery."}, {"id": "d", "text": "Activity guidance is part of initial management."}, {"id": "e", "text": "No activity limits are needed during acute phase."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Rest and activity restriction are recommended during the acute phase; avoid strenuous exercise until symptom-free.', 'Pericarditis - NCLEX', true, 92, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Second-line steroids" in Pericarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "Second-line steroids" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Prednisone is not first-line in routine cases."}, {"id": "b", "text": "SLE-related pericarditis should avoid steroids."}, {"id": "c", "text": "Steroids are mandatory first-line for all cases."}, {"id": "d", "text": "Steroids are considered when first-line therapy fails."}, {"id": "e", "text": "Specific etiologies (e.g., SLE) can justify steroid use."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Corticosteroids are reserved when NSAID/colchicine fails or for specific causes like SLE.', 'Pericarditis - NCLEX', true, 93, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Cause-specific caveats" in Pericarditis? (Select all that apply)', 'Which of the following are consistent with "Cause-specific caveats" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Uremic pericarditis is a context to avoid NSAIDs."}, {"id": "b", "text": "All causes are treated identically with NSAID monotherapy."}, {"id": "c", "text": "TB management is excluded from pericarditis care."}, {"id": "d", "text": "Bacterial pericarditis requires IV antibiotics."}, {"id": "e", "text": "TB pericarditis requires anti-TB therapy."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Avoid NSAIDs in uremic pericarditis; use IV antibiotics for bacterial causes and anti-TB therapy for TB.', 'Pericarditis - NCLEX', true, 94, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Tamponade emergency bridge" in Pericarditis? (Select all that apply)', 'During reassessment, which observations align with "Tamponade emergency bridge" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Emergency pericardiocentesis is required for tamponade."}, {"id": "b", "text": "Beck triad excludes tamponade."}, {"id": "c", "text": "Tamponade in pericarditis is managed with observation only."}, {"id": "d", "text": "Beck triad is listed with tamponade complication."}, {"id": "e", "text": "Tamponade is life-threatening."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Tamponade complication is identified by Beck triad and treated with emergency pericardiocentesis.', 'Pericarditis - NCLEX', true, 95, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Dressler management caveat" in Pericarditis are correct? (Select all that apply)', 'Which statements about "Dressler management caveat" in Pericarditis are correct? (Select all that apply)', '[{"id": "a", "text": "Anticoagulants are avoided because of pericardial bleeding risk."}, {"id": "b", "text": "Routine anticoagulation is first-line Dressler treatment."}, {"id": "c", "text": "NSAID plus colchicine is recommended for Dressler syndrome."}, {"id": "d", "text": "Dressler is autoimmune and post-MI/surgery."}, {"id": "e", "text": "Dressler treatment excludes NSAIDs."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Dressler syndrome is treated with NSAIDs + colchicine and anticoagulants are avoided due to bleeding risk into pericardium.', 'Pericarditis - NCLEX', true, 96, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Pericarditis, which findings or actions relate to "NCLEX triage anchor"? (Select all that apply)', 'For Pericarditis, which findings or actions relate to "NCLEX triage anchor"? (Select all that apply)', '[{"id": "a", "text": "Triage can ignore EKG in chest pain with suspected pericarditis."}, {"id": "b", "text": "Tamponade surveillance is unnecessary in pericarditis."}, {"id": "c", "text": "Pain pattern and position response are triage anchors."}, {"id": "d", "text": "Friction rub and EKG clues are high-yield assessments."}, {"id": "e", "text": "Monitor for progression to effusion/tamponade."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: In suspected pericarditis, prioritize pain pattern recognition, friction rub assessment, EKG interpretation, and tamponade surveillance.', 'Pericarditis - NCLEX', true, 97, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Hallmark synthesis" in Pericarditis? (Select all that apply)', 'The nurse is planning care. Which items apply to "Hallmark synthesis" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Localized-only ST elevation is required for diagnosis."}, {"id": "b", "text": "Friction rub is a hallmark."}, {"id": "c", "text": "Reciprocal ST depression is a hallmark of pericarditis."}, {"id": "d", "text": "Diffuse ST elevation with PR depression supports diagnosis."}, {"id": "e", "text": "Pleuritic positional pain is a hallmark."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Core hallmarks are pleuritic positional chest pain, friction rub, diffuse ST elevation, PR depression, and absent reciprocal ST changes.', 'Pericarditis - NCLEX', true, 98, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Definition" in Pericarditis? (Select all that apply)', 'Which of the following are consistent with "Definition" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Pericarditis is inflammation of heart valves."}, {"id": "b", "text": "Inflammation can progress to pericardial effusion."}, {"id": "c", "text": "Pericarditis is confined to coronary arteries."}, {"id": "d", "text": "The pericardium is the sac around the heart."}, {"id": "e", "text": "Pericarditis involves inflammation of pericardial layers."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis is inflammation of the pericardium, the fibrous sac surrounding the heart.', 'Pericarditis - NCLEX', true, 99, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Disease course" in Pericarditis? (Select all that apply)', 'During reassessment, which observations align with "Disease course" in Pericarditis? (Select all that apply)', '[{"id": "a", "text": "Recurrent forms are described."}, {"id": "b", "text": "Chronic constrictive forms are also listed."}, {"id": "c", "text": "Acute forms are described."}, {"id": "d", "text": "Pericarditis is always single-episode and never recurrent."}, {"id": "e", "text": "Constrictive disease is unrelated to pericarditis."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis can be acute, recurrent, or chronic constrictive.', 'Pericarditis - NCLEX', true, 100, 1, true);
END $$;
COMMIT;